import torch, torch.nn as nn

class SAE(nn.Module):
    def __init__(self, d_model, d_hidden):        # d_hidden >> d_model
        super().__init__()
        self.enc = nn.Linear(d_model, d_hidden)
        self.dec = nn.Linear(d_hidden, d_model, bias=False)

    def forward(self, x):
        z = torch.relu(self.enc(x))
        with torch.no_grad():                     # keep the dictionary unit-norm
            self.dec.weight.div_(self.dec.weight.norm(dim=0, keepdim=True))
        return self.dec(z), z

def loss_fn(x, x_hat, z, lam=1e-3):
    return ((x - x_hat) ** 2).sum(-1).mean() + lam * z.abs().sum(-1).mean()
